INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginnt der DHCPv6-Prozess immer mit einer Solicit-Nachricht?', 2, '[{"text": "Ja", "correct": true, "because": "Client initiiert Prozess"}, {"text": "Nein", "correct": false, "because": "Standardsequenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Schritte umfasst der DHCPv6-Prozess typischerweise?', 3, '[{"text": "4", "correct": true, "because": "Solicit, Advertise, Request, Reply"}, {"text": "2", "correct": false, "because": "Zu wenig"}, {"text": "6", "correct": false, "because": "Zu viele"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht folgt auf Solicit im DHCPv6-Prozess?', 4, '[{"text": "Advertise", "correct": true, "because": "Server antwortet mit Angebot"}, {"text": "Request", "correct": false, "because": "Client-Anfrage folgt später"}, {"text": "Reply", "correct": false, "because": "Abschlussnachricht"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Request bestätigt die Adresswahl. b) Reply schließt den Prozess ab.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) Client wählt, b) Server bestätigt"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim DHCPv6-Prozess?', 5, '[{"text": "Manuelle Konfiguration", "correct": true, "because": "Automatisierung ist Ziel"}, {"text": "Solicit-Nachricht", "correct": false, "because": "Startet Prozess"}, {"text": "Server-Antwort", "correct": false, "because": "Essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Advertise die letzte Nachricht im DHCPv6-Prozess ist?', 2, '[{"text": "Nein", "correct": true, "because": "Request und Reply folgen"}, {"text": "Ja", "correct": false, "because": "Nur zweiter Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht sendet der Client, um eine Adresse anzufordern?', 3, '[{"text": "Request", "correct": true, "because": "Client bestätigt Wahl"}, {"text": "Solicit", "correct": false, "because": "Initiale Suche"}, {"text": "Advertise", "correct": false, "because": "Server-Nachricht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind im DHCPv6-Prozess essenziell?', 5, '[{"text": "Solicit", "correct": true, "because": "Startet Prozess"}, {"text": "Reply", "correct": true, "because": "Schließt Zuweisung ab"}, {"text": "Manual Config", "correct": false, "because": "Nicht Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Solicit sucht Server. b) Advertise ist optional. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, notwendig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht im DHCPv6-Prozess?', 4, '[{"text": "Solicit", "correct": false, "because": "Initiierung"}, {"text": "Reply", "correct": false, "because": "Abschluss"}, {"text": "Statische IPs", "correct": true, "because": "Dynamisch geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Request die erste Nachricht im DHCPv6-Prozess?', 2, '[{"text": "Nein", "correct": true, "because": "Solicit kommt zuerst"}, {"text": "Ja", "correct": false, "because": "Falsche Reihenfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachrichten tauschen Client und Server aus?', 4, '[{"text": "Solicit und Request", "correct": true, "because": "Client sendet"}, {"text": "Advertise und Reply", "correct": true, "because": "Server antwortet"}, {"text": "Ping", "correct": false, "because": "Nicht Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Reply die Adresse anfragt. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Reply bestätigt, Request fragt"}, {"text": "Ja", "correct": false, "because": "Falsche Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im DHCPv6-Prozess?', 3, '[{"text": "Reihenfolge der Nachrichten", "correct": true, "because": "Definiert Ablauf"}, {"text": "Manuelle Eingriffe", "correct": false, "because": "Automatisierung Ziel"}, {"text": "Subnetzgröße", "correct": false, "because": "Netzwerk-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Advertise bietet Adressen an. b) Solicit ist die Antwort des Servers.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) falsch, Client-Nachricht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet der DHCPv6-Prozess?', 5, '[{"text": "Klare Struktur", "correct": true, "because": "4 definierte Schritte"}, {"text": "Automatisierte Zuweisung", "correct": true, "because": "Keine manuelle Arbeit"}, {"text": "Statische Adressen", "correct": false, "because": "Dynamisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im DHCPv6-Prozess unwichtig?', 3, '[{"text": "Client-Server-Kommunikation", "correct": false, "because": "Kern des Prozesses"}, {"text": "Nachrichtenfolge", "correct": false, "because": "Definiert Ablauf"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kommt Reply vor Request im DHCPv6-Prozess?', 2, '[{"text": "Nein", "correct": true, "because": "Request vor Reply"}, {"text": "Ja", "correct": false, "because": "Falsche Reihenfolge"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Advertise mehrere Adressen anbieten kann?', 3, '[{"text": "Ja", "correct": true, "because": "Server kann Optionen senden"}, {"text": "Nein", "correct": false, "because": "Flexibilität gegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachricht wählt der Client im DHCPv6-Prozess?', 4, '[{"text": "Request", "correct": true, "because": "Bestätigt Angebot"}, {"text": "Advertise", "correct": false, "because": "Server-Angebot"}, {"text": "Solicit", "correct": false, "because": "Initiale Suche"}]');
